    context: context,
    reliefUsed: true,
    retried: false,
    terminal: (
      await _finishWithoutStream(
        context,
        emit,
        _terminalMessage(
          config.model,
          StopReason.error,
          '$contextWindowExhaustedMarker: the outgoing context is '
          '~$tokens tokens, '
          'the ${config.model.id} effective window is $window. The request '
