            m.content.any(
              (b) =>
                  b is TextContent &&
                  b.text.startsWith('[image dropped: '),
            ),
      ),
      isTrue,
      reason: 'the evicted read image becomes the placeholder text',
    );
    // The placeholder names the content-key preview the /images surface
    // uses — same identifier, no silent rebinding (AC7).
